@RestControllerAdvice
public class ApiExceptionHandler {

    private static final Logger log = LoggerFactory.getLogger(ApiExceptionHandler.class);

    @ExceptionHandler(NotFoundException.class)
    ProblemDetail notFound(NotFoundException ex) {
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(HttpStatus.NOT_FOUND, ex.getMessage());
        pd.setType(URI.create("https://learnhub.dev/errors/topic-not-found"));
        pd.setTitle("学习项不存在");
        pd.setProperty("code", ex.getCode());
        pd.setProperty("traceId", traceId());
        return pd;
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    ProblemDetail invalidBody(MethodArgumentNotValidException ex) {
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, "参数校验失败");
        pd.setType(URI.create("https://learnhub.dev/errors/validation-failed"));
        pd.setProperty("code", "VALIDATION_FAILED");
        pd.setProperty("errors", ex.getBindingResult().getFieldErrors().stream()
                .map(e -> Map.of("field", e.getField(), "message", e.getDefaultMessage()))
                .toList());
        pd.setProperty("traceId", traceId());
        return pd;
    }

    @ExceptionHandler(Exception.class)
    ProblemDetail fallback(Exception ex, HttpServletRequest req) {
        log.error("未处理异常: {} {}", req.getMethod(), req.getRequestURI(), ex);
        ProblemDetail pd = ProblemDetail.forStatusAndDetail(
                HttpStatus.INTERNAL_SERVER_ERROR, "服务暂时不可用");
        pd.setProperty("code", "INTERNAL_ERROR");
        pd.setProperty("traceId", traceId());
        return pd;
    }

    private String traceId() {
        return Optional.ofNullable(MDC.get("traceId")).orElse("unknown");
    }
}

@Component
@Order(Ordered.HIGHEST_PRECEDENCE)
public class TraceIdFilter extends OncePerRequestFilter {

    public static final String HEADER = "X-Request-Id";
    private static final int MAX_LEN = 64;

    @Override
    protected void doFilterInternal(HttpServletRequest req, HttpServletResponse res,
                                    FilterChain chain) throws ServletException, IOException {
        String traceId = req.getHeader(HEADER);
        if (traceId == null || traceId.isBlank() || traceId.length() > MAX_LEN) {
            traceId = UUID.randomUUID().toString().replace("-", "");
        }

        MDC.put("traceId", traceId);
        res.setHeader(HEADER, traceId);
        try {
            chain.doFilter(req, res);
        } finally {
            MDC.remove("traceId");
        }
    }
}

export interface ApiErrorBody {
  code?: string
  message?: string
  traceId?: string
}

export class ApiError extends Error {
  constructor(
    readonly status: number,
    readonly code: string,
    message: string,
    readonly traceId?: string,
  ) {
    super(message)
  }
}

export async function request<T>(url: string, init: RequestInit = {}): Promise<T> {
  const res = await fetch(url, init)
  if (res.ok) {
    return (res.status === 204 ? undefined : await res.json()) as T
  }

  let body: ApiErrorBody = {}
  try {
    body = (await res.json()) as ApiErrorBody
  } catch {
    // 错误体不是 JSON（网关 502、超时页）时保留状态码
  }

  if (res.status === 401) {
    setUserToken('')
    router.push({ name: 'login', query: { redirect: router.currentRoute.value.fullPath } })
  }

  const traceId = res.headers.get('X-Request-Id') ?? body.traceId
  throw new ApiError(
    res.status,
    body.code ?? `HTTP_${res.status}`,
    body.message ?? '请求失败，请稍后重试',
    traceId ?? undefined,
  )
}
